B.ah3=new A.w("\u0412\u0435\u0440\u0430","\u041a\u0430\u043a \u0437\u0432\u0443\u0447\u0438\u0442 \u0448\u0430\u0445\u0430\u0434\u0430?","\xab\u0410\u0448\u0445\u0430\u0434\u0443 \u0430\u043b\u044c-\u043b\u044f \u0438\u043b\u044f\u0445\u0430 \u0438\u043b\u043b\u044f\u043b\u043b\u0430\u0445, \u0432\u0430 \u0430\u0448\u0445\u0430\u0434\u0443 \u0430\u043d\u043d\u0430 \u041c\u0443\u0445\u0430\u043c\u043c\u0430\u0434\u0430\u043d \u0440\u0430\u0441\u0443\u043b\u044e\u043b\u043b\u0430\u0445\xbb \u2014 \xab\u0421\u0432\u0438\u0434\u0435\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0443\u044e, \u0447\u0442\u043e \u043d\u0435\u0442 \u0431\u043e\u0436\u0435\u0441\u0442\u0432\u0430, \u043a\u0440\u043e\u043c\u0435 \u0410\u043b\u043b\u0430\u0445\u0430, \u0438 \u0441\u0432\u0438\u0434\u0435\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0443\u044e, \u0447\u0442\u043e \u041c\u0443\u0445\u0430\u043c\u043c\u0430\u0434 \u2014 \u041f\u043e\u0441\u043b\u0430\u043d\u043d\u0438\u043a \u0410\u043b\u043b\u0430\u0445\u0430\xbb.")
B.aib=new A.w("\u0412\u0435\u0440\u0430","\u0427\u0442\u043e \u0442\u0430\u043a\u043e\u0435 \u0448\u0438\u0440\u043a?","\u041f\u0440\u0438\u0434\u0430\u0432\u0430\u0442\u044c \u0410\u043b\u043b\u0430\u0445\u0443 \u0441\u043e\u0442\u043e\u0432\u0430\u0440\u0438\u0449\u0435\u0439 \u2014 \u0432 \u0431\u043e\u0436\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0441\u0442\u0438 \u0438\u043b\u0438 \u0432 \u043f\u043e\u043a\u043b\u043e\u043d\u0435\u043d\u0438\u0438. \u042d\u0442\u043e \u0441\u0430\u043c\u044b\u0439 \u0442\u044f\u0436\u0451\u043b\u044b\u0439 \u0433\u0440\u0435\u0445: \u0410\u043b\u043b\u0430\u0445 \u043d\u0435 \u043f\u0440\u043e\u0449\u0430\u0435\u0442 \u0435\u0433\u043e \u0442\u043e\u043c\u0443, \u043a\u0442\u043e \u0443\u043c\u0435\u0440 \u043d\u0430 \u043d\u0451\u043c \u0431\u0435\u0437 \u043f\u043e\u043a\u0430\u044f\u043d\u0438\u044f (\u041a\u043e\u0440\u0430\u043d, 4:48).")
B.ak_=new A.w("\u0412\u0435\u0440\u0430","\u041a\u0430\u043a\u043e\u0439 \u0430\u043a\u044b\u0434\u044b \u043f\u0440\u0438\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u044e\u0442\u0441\u044f \u043c\u0443\u0441\u0443\u043b\u044c\u043c\u0430\u043d\u0435 \u041a\u0430\u0437\u0430\u0445\u0441\u0442\u0430\u043d\u0430?","\u0410\u043a\u044b\u0434\u044b \u0430\u0445\u043b\u044e-\u0441\u0443\u043d\u043d\u0430 \u0432\u0430\u043b\u044c-\u0434\u0436\u0430\u043c\u0430\u0430 \u043f\u043e \u0448\u043a\u043e\u043b\u0435 \u0438\u043c\u0430\u043c\u0430 \u0410\u0431\u0443 \u041c\u0430\u043d\u0441\u0443\u0440\u0430 \u0430\u043b\u044c-\u041c\u0430\u0442\u0443\u0440\u0438\u0434\u0438, \u0430 \u0432 \u0444\u0438\u043a\u0445\u0435 \u2014 \u0445\u0430\u043d\u0430\u0444\u0438\u0442\u0441\u043a\u043e\u0433\u043e \u043c\u0430\u0437\u0445\u0430\u0431\u0430.")
